<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {emptyDocument,getVisitorState,placeName,postVisitor,previewUrl,roleLabels,type VContent,type VPayload} from './visitor-content-api';
const route=useRoute(),router=useRouter(),payload=ref<VPayload|null>(null),item=ref<VContent|null>(null),draft=ref<any>(emptyDocument()),message=ref(''),busy=ref(false),newPlace=ref(''),newNav=ref('');
const clone=<T>(value:T):T=>JSON.parse(JSON.stringify(value));
const isNew=computed(()=>route.params.id==='new');
const validPlaces=computed(()=>payload.value?.places.filter(place=>!place.deleted_at&&!place.duplicate_of_place_id)||[]);
const themes=computed(()=>payload.value?.state.themes||[]);
const linkedAlerts=computed(()=>payload.value?.state.alerts.filter(alert=>!alert.deletedAt&&(draft.value.alertIds.includes(alert.id)||alert.contentIds.includes(item.value?.id||'')||alert.placeCodes.some(code=>draft.value.placeLinks.some((link:any)=>link.placeCode===code))))||[]);
onMounted(async()=>{payload.value=await getVisitorState();if(!isNew.value){item.value=payload.value.state.contents.find(content=>content.id===route.params.id)||null;if(!item.value){message.value='游客内容不存在';return;}draft.value=clone(item.value.draft);}});
function place(code:string){return placeName(payload.value?.places||[],code);}
function move(list:any[],index:number,delta:number){const target=index+delta;if(target<0||target>=list.length)return;[list[index],list[target]]=[list[target],list[index]];list.forEach((entry,i)=>entry.sequence=(i+1)*10);}
function addPlace(){if(!newPlace.value||draft.value.placeLinks.some((link:any)=>link.placeCode===newPlace.value))return;draft.value.placeLinks.push({placeCode:newPlace.value,role:'other',sequence:(draft.value.placeLinks.length+1)*10});newPlace.value='';}
function addNav(){if(!newNav.value||draft.value.navigationTargets.some((nav:any)=>nav.placeCode===newNav.value))return;draft.value.navigationTargets.push({placeCode:newNav.value,label:place(newNav.value),sequence:(draft.value.navigationTargets.length+1)*10,isDefault:!draft.value.navigationTargets.length});newNav.value='';}
function setDefault(index:number){draft.value.navigationTargets.forEach((nav:any,i:number)=>nav.isDefault=i===index);}
function addModule(){draft.value.modules.push({id:crypto.randomUUID(),kind:'text',title:'新内容段落',body:'',items:[],columns:[],hidden:false,sequence:(draft.value.modules.length+1)*10});}
function setItems(module:any,event:Event){module.items=(event.target as HTMLTextAreaElement).value.split('\n').map(value=>value.trim()).filter(Boolean);}
async function save(show=true){busy.value=true;message.value='';try{const document=clone(draft.value);let result:any;if(isNew.value){result=await postVisitor('/create',{expected_store_version:payload.value!.state.version,document});item.value=result.item;await router.replace('/visitor-content/'+result.item.id);}else result=await postVisitor(`/${item.value!.id}/save`,{expected_version:item.value!.version,document});item.value=result.item;draft.value=clone(result.item.draft);if(payload.value)payload.value.state.version=result.storeVersion;if(show)message.value=result.item.status==='published'?'工作草稿已保存，游客端仍显示上次发布版本':'草稿已保存';return result.item;}catch(e){message.value=(e as Error).message;throw e;}finally{busy.value=false;}}
async function publish(){try{const saved=await save(false);busy.value=true;const result=await postVisitor<any>(`/${saved.id}/publish`,{expected_version:saved.version});item.value=result.item;draft.value=clone(result.item.draft);message.value='已保存，游客端刷新后立即看到最新内容';}catch{}finally{busy.value=false;}}
async function preview(){const tab=window.open('about:blank','_blank');try{const saved=await save(false);if(tab)tab.location.href=previewUrl(saved.id);message.value='草稿预览已打开，普通游客看不到该版本';}catch{tab?.close();}}
async function action(name:'hide'|'delete'|'copy'){if(name==='delete'&&!confirm(`确认将“${draft.value.title}”移入游客内容回收区？`))return;busy.value=true;try{if(name==='copy'){const result=await postVisitor<any>(`/${item.value!.id}/copy`,{expected_store_version:payload.value!.state.version});await router.push('/visitor-content/'+result.item.id);location.reload();return;}const result=await postVisitor<any>(`/${item.value!.id}/${name}`,{expected_version:item.value!.version});item.value=result.item;message.value=name==='hide'?'内容已隐藏，游客端不再显示':'已移入游客内容回收区';if(name==='delete')await router.push('/visitor-content');}catch(e){message.value=(e as Error).message;}finally{busy.value=false;}}
</script>

<template>
 <div class="workspace-page visitor-editor">
  <div class="workspace-title"><div><p class="kicker">文字内容</p><h1>{{isNew?'新建内容':draft.title||'编辑内容'}}</h1><p>{{item?.status==='hidden'?'这项内容当前未显示给游客。':'修改完成后，点一次“保存并更新游客端”即可。'}}</p></div><RouterLink to="/visitor-content" class="button secondary quiet">返回列表</RouterLink></div>
  <p v-if="message" class="inline-message" role="status">{{message}}</p>

  <section id="basic" class="editor-section"><div class="section-heading"><span>01</span><div><h2>基本信息</h2><p>后台怎么认、游客怎么读。</p></div></div><div class="form-grid"><label>内部名称<input v-model.trim="draft.internalName" maxlength="160"></label><label>游客标题<input v-model.trim="draft.title" maxlength="160"></label><label class="wide">一句简介<textarea v-model.trim="draft.summary" rows="3" maxlength="500"></textarea></label><label>访问路径<input v-model.trim="draft.slug" maxlength="80" placeholder="例如 moonbay"></label><label>页面类型<select v-model="draft.presentation.kind"><option value="outdoor">户外</option><option value="nature">自然</option><option value="museum">展馆</option><option value="food">吃东西</option></select></label></div></section>

  <section id="themes" class="editor-section"><div class="section-heading"><span>02</span><div><h2>游客怎么找到它</h2><p>允许同时选择多个主题。</p></div></div><div class="choice-grid"><label v-for="theme in themes" :key="theme.id" class="choice-card"><input v-model="draft.themeIds" type="checkbox" :value="theme.id"><span><strong>{{theme.name}}</strong><small>{{theme.description}}</small><input v-if="draft.themeIds.includes(theme.id)" v-model.number="draft.themeOrder[theme.id]" type="number" min="0" step="10" placeholder="主题内顺序"></span></label></div><label class="kids-choice"><input v-model="draft.familyFriendly" type="checkbox">适合带孩子</label></section>

  <section id="arrival" class="editor-section"><div class="section-heading"><span>03</span><div><h2>到了以后怎么办</h2><p>地点只保存引用，不复制坐标。</p></div></div>
   <h3>组成地点与角色</h3><div class="add-row"><select v-model="newPlace"><option value="">选择现有地点</option><option v-for="p in validPlaces" :key="p.code" :value="p.code">{{p.name}} · {{p.code}}</option></select><button class="secondary" @click="addPlace">添加地点</button></div>
   <div class="relation-list"><article v-for="(link,index) in draft.placeLinks" :key="link.placeCode"><span class="relation-order">{{index+1}}</span><div><strong>{{place(link.placeCode)}}</strong><small>{{link.placeCode}}</small></div><select v-model="link.role"><option v-for="(label,key) in roleLabels" :key="key" :value="key">{{label}}</option></select><div class="row-buttons"><button class="icon-button" @click="move(draft.placeLinks,index,-1)">↑</button><button class="icon-button" @click="move(draft.placeLinks,index,1)">↓</button><button class="remove-button" @click="draft.placeLinks.splice(index,1)">移除</button></div></article></div>
   <h3>导航目标</h3><p class="section-note">默认目标必须是未删除且具有当前正式坐标的地点。</p><div class="add-row"><select v-model="newNav"><option value="">选择导航地点</option><option v-for="p in validPlaces.filter(p=>p.has_coordinate)" :key="p.code" :value="p.code">{{p.name}} · {{p.code}}</option></select><button class="secondary" @click="addNav">添加导航</button></div>
   <div class="relation-list nav-relations"><article v-for="(nav,index) in draft.navigationTargets" :key="nav.placeCode"><input type="radio" :checked="nav.isDefault" name="default-nav" aria-label="设为默认" @change="setDefault(index)"><div><strong>{{place(nav.placeCode)}}</strong><small>{{nav.placeCode}}</small></div><input v-model="nav.label" maxlength="80" placeholder="游客端显示名称"><div class="row-buttons"><button class="icon-button" @click="move(draft.navigationTargets,index,-1)">↑</button><button class="icon-button" @click="move(draft.navigationTargets,index,1)">↓</button><button class="remove-button" @click="draft.navigationTargets.splice(index,1)">移除</button></div></article></div>
  </section>

  <section id="alerts" class="editor-section"><div class="section-heading"><span>04</span><div><h2>现在有什么变化</h2><p>短提醒独立维护，无需重写整篇内容。</p></div></div><div v-if="linkedAlerts.length" class="alert-list"><article v-for="alert in linkedAlerts" :key="alert.id"><span class="alert-level" :class="'level-'+alert.level">{{alert.level}}</span><p>{{alert.text}}</p><strong>{{alert.enabled?'启用中':'已关闭'}}</strong></article></div><p v-else class="empty-inline">当前没有关联提醒。</p><RouterLink to="/visitor-alerts" class="button secondary">管理现场提醒</RouterLink></section>

  <section id="modules" class="editor-section"><div class="section-heading"><span>05</span><div><h2>页面内容</h2><p>简单模块化，不使用复杂富文本。</p></div><button class="secondary" @click="addModule">新增模块</button></div><div class="module-editor-list"><article v-for="(module,index) in draft.modules" :key="module.id" class="module-editor"><div class="module-head"><span>{{String(index+1).padStart(2,'0')}}</span><select v-model="module.kind"><option value="text">文字段落</option><option value="steps">步骤</option><option value="numbered">编号列表</option><option value="checklist">清单</option><option value="timeline">时间线</option><option value="question">提醒问题</option><option value="route_segment">路线分段</option></select><label class="inline-check"><input v-model="module.hidden" type="checkbox">隐藏</label></div><label>模块标题<input v-model.trim="module.title" maxlength="160"></label><label>正文<textarea v-model="module.body" rows="3"></textarea></label><label>列表内容<small>每行一项</small><textarea :value="module.items.join('\n')" rows="4" @input="setItems(module,$event)"></textarea></label><div class="row-buttons"><button class="quiet" @click="move(draft.modules,index,-1)">上移</button><button class="quiet" @click="move(draft.modules,index,1)">下移</button><button class="remove-button" @click="draft.modules.splice(index,1)">删除模块</button></div></article></div></section>

  <details v-if="item" class="history-panel"><summary>更多操作与修改历史</summary><div class="advanced-content-actions"><button class="secondary" :disabled="busy" @click="preview">预览修改</button><button class="quiet" @click="action('copy')">复制一份</button><button v-if="item.status==='published'" class="quiet" @click="action('hide')">暂时隐藏</button><button class="danger-link" @click="action('delete')">移入回收区</button></div><article v-for="history in payload?.state.history.filter(row=>row.objectId===item?.id).slice(0,20)" :key="history.id"><strong>{{history.changeType}}</strong><span>{{new Date(history.at).toLocaleString('zh-CN')}}</span><small>{{history.beforeSummary}} → {{history.afterSummary}}</small></article></details>
  <div class="editor-action-bar simple"><RouterLink to="/visitor-content" class="button secondary">取消</RouterLink><button class="primary-action" :disabled="busy" @click="publish">{{busy?'正在保存…':'保存并更新游客端'}}</button></div>
 </div>
</template>




